      description: { story: "`scale="log"` spreads values by ratio, so a frequency or zoom row gives the low end as much room as the high end. Values round onto `step`, or keep four significant digits without one. Arrow keys move 1% of the row (10% with Shift). A log scale needs `min` above zero." },
      source: { code: "import { Control } from "@/registry/erbium/ui/control";

const hertz = (value: number) => (value >= 1000 ? `${value / 1000} kHz` : `${value} Hz`);

